INSERT INTO `logelak` VALUES (1,'Sukalde duen bi pertsonentzako logela',2,0,1,0,0,'Logela lasai eta egonkorra, bi pertsonentzako egokia, bertan sukaldaritza egiteko aukera izango duzu, sukalde oso bat du.',50.00,'https://cf.bstatic.com/xdata/images/hotel/max500/274163128.jpg?k=a7309f660d09ebf172ccaf93f8640fe6a0817595bafcb34b9b774dba82f80f1e&o=','https://cf.bstatic.com/xdata/images/hotel/max500/274162964.jpg?k=60e5e0c38b3437efb3068da9324b6f5b9efd221a4498b4d8882c497af29a1cad&o=','https://cf.bstatic.com/xdata/images/hotel/max500/244000568.jpg?k=51395e6dec4b5330023686f792166fa05bd6aa7d973b511d45308a07ca7521d6&o=','https://cf.bstatic.com/xdata/images/hotel/max500/245041323.jpg?k=8068e2861ebafd3bc4dfe3df0f8ad83940f4302fff6d28b02761901505b48eb8&o=','https://cf.bstatic.com/xdata/images/hotel/max500/243973134.jpg?k=9d04c52a4dfe8e8cc6b1afbc109ea4878ebe0fb6442b4ae9e6e8dbf6ff69b5af&o=',''),(2,'Sukalde eta telebista duen bi pertsonentzako gela',2,1,1,0,0,'Bi pertsonentzako logela erosoa, telebista eta sukaldearekin, atseden hartu eta gustuko platerak prestatu ahal izango dituzu.',45.00,'https://cf.bstatic.com/xdata/images/hotel/max500/274163128.jpg?k=a7309f660d09ebf172ccaf93f8640fe6a0817595bafcb34b9b774dba82f80f1e&o=','https://cf.bstatic.com/xdata/images/hotel/max500/274162964.jpg?k=60e5e0c38b3437efb3068da9324b6f5b9efd221a4498b4d8882c497af29a1cad&o=','https://cf.bstatic.com/xdata/images/hotel/max500/243973462.jpg?k=3a6310514553c37e55d6923df47dd6f646039bb2f2c7ce499466c4879f9e4e57&o=','https://cf.bstatic.com/xdata/images/hotel/max500/244000568.jpg?k=51395e6dec4b5330023686f792166fa05bd6aa7d973b511d45308a07ca7521d6&o=','https://cf.bstatic.com/xdata/images/hotel/max500/245041323.jpg?k=8068e2861ebafd3bc4dfe3df0f8ad83940f4302fff6d28b02761901505b48eb8&o=','https://cf.bstatic.com/xdata/images/hotel/max500/243973134.jpg?k=9d04c52a4dfe8e8cc6b1afbc109ea4878ebe0fb6442b4ae9e6e8dbf6ff69b5af&o='),(3,'Bainu eta balkoia duen hiru pertsonentzako gela',3,0,1,1,0,'Hirurentzako logela, bainugela prib